// Siegfried, Act 2: complete public-domain German and machine-assisted English working translation.
export const siegfriedAct2Scenes = [{"number":1,"originalHeading":"ERSTE SZENE","translatedHeading":"First Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"In Wald und Nacht vor Neidhöhl' halt' ich Wacht:","translatedTitle":"In the forest and at night before Neidhöhl' I keep watch:","participants":["ALBERICH","DER WANDERER","WANDERER"],"sourceStartIndex":0,"sourceLineCount":63,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Tiefer Wald. Ganz im Hintergrunde die Öffnung einer Höhle. Der Boden hebt sich bis zur Mitte der Bühne, wo er eine kleine Hochebene bildet; von da senkt er sich nach hinten, der Höhle zu, wieder abwärts, so dass von dieser nur der obere Teil der Öffnung dem Zuschauer sichtbar ist. Links gewahrt man durch Waldbäume eine zerklüftete Felsenwand. Finstere Nacht, am dichtesten über dem Hintergrunde, wo anfänglich der Blick des Zuschauers gar nichts zu unterscheiden vermag\nAlberich, Fafner, Wanderer\nan der Felsenwand zur Seite gelagert, düster brütend","translation":"Deep forest. In the far background, the opening of a cave. The ground rises to the center of the stage, forming a small plateau; from there it slopes downwards again towards the cave, so that only the upper part of the opening is visible to the viewer. To the left, a craggy rock face can be glimpsed through the trees. Pitch-black night, densest over the background, where initially the viewer's gaze cannot discern anything at all.\nAlberich, Fafner, Wanderer\nLaid sideways against the rock face, brooding gloomily.","literalText":true,"sourceStartIndex":0,"sourceLineCount":3},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"In Wald und Nacht vor Neidhöhl' halt' ich Wacht:\nes lauscht mein Ohr, mühvoll lugt mein Aug'.\nBanger Tag, bebst du schon auf?\nDämmerst du dort durch das Dunkel her?","translation":"In the forest and at night before Neidhöhl' I keep watch:\nMy ear listens, my eye laboriously peers.\nBanger day, are you already shaking?\nAre you skulking through the darkness there?","literalText":true,"sourceStartIndex":3,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Aus dem Walde von rechts her erhebt sich ein Sturmwind; ein bläulicher Glanz leuchtet von ebendaher","translation":"A storm wind rises from the forest on the right; a bluish gleam shines from the same direction.","literalText":true,"sourceStartIndex":7,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Welcher Glanz glitzert dort auf?\nNäher schimmert ein heller Schein;\nes rennt wie ein leuchtendes Ross,\nbricht durch den Wald brausend daher.\nNaht schon des Wurmes Würger?\nIst's schon, der Fafner fällt?","translation":"What glittering gleam is there?\nA bright glow shimmers closer;\nIt runs like a shining horse,\nbursts forth through the forest with a roar.\nIs the worm's strangler already approaching?\nIs it already Fafner falling?","literalText":true,"sourceStartIndex":8,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Der Sturmwind legt sich wieder; der Glanz verlischt","translation":"The storm wind subsides; the gleam fades.","literalText":true,"sourceStartIndex":14,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Das Licht erlischt,\nder Glanz barg sich dem Blick:\nNacht ist's wieder.","translation":"The light goes out,\nThe brilliance was hidden from view:\nIt's night again.","literalText":true,"sourceStartIndex":15,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Der Wanderer tritt aus dem Wald und hält Alberich gegenüber an","translation":"The hiker emerges from the forest and stops opposite Alberich.","literalText":true,"sourceStartIndex":18,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Wer naht dort schimmernd im Schatten?","translation":"Who approaches there, shimmering in the shadows?","literalText":true,"sourceStartIndex":19,"sourceLineCount":1},{"speaker":"DER WANDERER","speakerTranslation":"DER WANDERER","original":"Zur Neidhöhle fuhr ich bei Nacht:\nwen gewahr' ich im Dunkel dort?","translation":"I drove to the Envy Cave at night:\nWhom do I perceive in the darkness there?","literalText":true,"sourceStartIndex":20,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Wie aus einem plötzlich zerreissenden Gewölk bricht Mondschein herein und beleuchtet des Wanderers Gestalt\nerkennt den Wanderer, fährt erschrocken zurück, bricht aber sogleich in höchste Wut aus","translation":"As if from a suddenly tearing cloud, moonlight bursts in and illuminates the wanderer's figure.\nHe recognizes the hiker, recoils in fright, but immediately flies into a rage.","literalText":true,"sourceStartIndex":22,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Du selbst lässt dich hier sehn?\nWas willst du hier?\nFort, aus dem Weg!\nVon dannen, schamloser Dieb!","translation":"Are you showing yourself here?\nWhat do you want here?\nGet out of the way!\nGet out of here, shameless thief!","literalText":true,"sourceStartIndex":24,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ruhig","translation":"quiet","literalText":true,"sourceStartIndex":28,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Schwarz-Alberich, schweifst du hier?\nHütest du Fafners Haus?","translation":"Schwarz-Alberich, are you wandering here?\nAre you looking after Fafner's house?","literalText":true,"sourceStartIndex":29,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Jagst du auf neue Neidtat umher?\nWeile nicht hier, weiche von hinnen!\nGenug des Truges tränkte die Stätte mit Not.\nDrum, du Frecher, lass sie jetzt frei!","translation":"Are you hunting for a new act of envy?\nDon't linger here, leave this place!\nEnough of the deception drowned the place in misery.\nSo, you cheeky fellow, let them go now!","literalText":true,"sourceStartIndex":31,"sourceLineCount":4},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Zu schauen kam ich,\nnicht zu schaffen:\nwer wehrte mir Wand'rers Fahrt?","translation":"I came to look,\nimpossible:\nWho would deny me Wanderer's journey?","literalText":true,"sourceStartIndex":35,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lacht tückisch auf","translation":"laughs wickedly","literalText":true,"sourceStartIndex":38,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Du Rat wütender Ränke!\nWär' ich dir zulieb\ndoch noch dumm wie damals,\nals du mich Blöden bandest,\nwie leicht geriet' es,\nden Ring mir nochmals zu rauben!\nHab' acht! Deine Kunst kenne ich wohl;\ndoch wo du schwach bist,\nblieb mir auch nicht verschwiegen.\nMit meinen Schätzen zahltest du Schulden;\nmein Ring lohnte der Riesen Müh',\ndie deine Burg dir gebaut.\nWas mit den Trotzigen einst du vertragen,\ndes Runen wahrt noch heut'\ndeines Speeres herrischer Schaft.\nNicht du darfst, was als Zoll du gezahlt,\nden Riesen wieder entreissen:\ndu selbst zerspelltest deines Speeres Schaft;\nin deiner Hand der herrische Stab,\nder starke, zerstiebte wie Spreu!","translation":"You council of furious intrigues!\nIf I were too kind to you\nstill as stupid as back then,\nwhen you tied me up like a fool,\nhow easy it was,\nto steal the ring from me again!\nTake heed! I am well acquainted with your art;\nbut where you are weak,\nIt didn't remain a secret from me either.\nYou paid off debts with my treasures;\nMy ring was worth the giant's trouble,\nwho built your castle for you.\nWhat you once put up with the defiant ones,\nthe runes still preserve today\nthe commanding shaft of your spear.\nYou are not entitled to what you paid in customs duties.\nwrest the giants back from the giants:\nYou yourself shattered the shaft of your spear;\nin your hand the commanding staff,\nThe strong one scattered like chaff!","literalText":true,"sourceStartIndex":39,"sourceLineCount":20},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Durch Vertrages Treuerunen\nband er dich Bösen mir nicht:\ndich beugt' er mir durch seine Kraft;\nzum Krieg drum wahr' ich ihn wohl!","translation":"Through contractual loyalty runs\nHe did not bind you evil me:\nHe bent you to my will by his strength;\nI believed in it, that's why I was there for the war!","literalText":true,"sourceStartIndex":59,"sourceLineCount":4}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Wie stolz du dräust in trotziger Stärke,","translatedTitle":"How proudly you loom in defiant strength,","participants":["ALBERICH","WANDERER","FAFNER","FAFNERS STIMME"],"sourceStartIndex":63,"sourceLineCount":75,"turns":[{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Wie stolz du dräust in trotziger Stärke,\nund wie dir's im Busen doch bangt!\nVerfallen dem Tod durch meinen Fluch\nist des Hortes Hüter:\nwer wird ihn beerben?\nWird der neidliche Hort\ndem Niblungen wieder gehören?\nDas sehrt dich mit ew'ger Sorge!\nDenn fass' ich ihn wieder einst in der Faust,\nanders als dumme Riesen\nüb' ich des Ringes Kraft:\ndann zittre der Helden heiliger Hüter!\nWalhalls Höhen stürm' ich mit Hellas Heer:\nder Welt walte dann ich!","translation":"How proudly you loom in defiant strength,\nand how anxious you feel in your breast!\nDoomed to death by my curse\nis the keeper of the hoard:\nWho will succeed him?\nWill the envious hoard\nbelong to the Nibelungs again?\nThis gazes upon you with eternal sorrow!\nFor if I ever grasp him again in my fist,\nunlike stupid giants\nI practice the ring's power:\nThen tremble the heroes, holy guardians!\nI will storm the heights of Valhalla with the army of Greece:\nI will rule the world then!","literalText":true,"sourceStartIndex":63,"sourceLineCount":14},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ruhig","translation":"quiet","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Deinen Sinn kenn' ich wohl;\ndoch sorgt er mich nicht.\nDes Ringes waltet, wer ihn gewinnt.","translation":"I know your intentions well;\nBut he doesn't worry me.\nThe ring is the one who wins it.","literalText":true,"sourceStartIndex":78,"sourceLineCount":3},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Wie dunkel sprichst du,\nwas ich deutlich doch weiss!\nAn Heldensöhne hält sich dein Trotz,","translation":"How dark your speech is,\nWhich I clearly know!\nYour defiance clings to the sons of heroes,","literalText":true,"sourceStartIndex":81,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"höhnisch","translation":"mocking","literalText":true,"sourceStartIndex":84,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"die traut deinem Blute entblüht.\nPflegtest du wohl eines Knaben,\nder klug die Frucht dir pflücke,","translation":"The one that blossoms from your blood.\nDid you perhaps care for a boy?\nHe who wisely plucks the fruit for you,","literalText":true,"sourceStartIndex":85,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"immer heftiger","translation":"increasingly violent","literalText":true,"sourceStartIndex":88,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"die du nicht brechen darfst?","translation":"which you must not break?","literalText":true,"sourceStartIndex":89,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Mit mir nicht, hadre mit Mime:\ndein Bruder bringt dir Gefahr;\neinen Knaben führt er daher,\nder Fafner ihm fällen soll.\nNichts weiss der von mir;\nder Niblung nützt ihn für sich.\nDrum sag' ich dir, Gesell:\ntue frei, wie dir's frommt!","translation":"Not with me, quarrel with Mime:\nYour brother brings you danger;\nHe therefore leads a boy,\nFafner is supposed to cut him down.\nHe knows nothing about me;\nThe Nibelung uses it for its own benefit.\nTherefore I tell you, fellow:\nDo as you see fit!","literalText":true,"sourceStartIndex":90,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Alberich macht eine Gebärde heftiger Neugierde","translation":"Alberich makes a gesture of intense curiosity.","literalText":true,"sourceStartIndex":98,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Höre mich wohl, sei auf der Hut!\nNicht kennt der Knabe den Ring;\ndoch Mime kundet' ihn aus.","translation":"Listen carefully, be on your guard!\nThe boy does not know the ring;\nBut Mime warned him.","literalText":true,"sourceStartIndex":99,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"heftig","translation":"violent","literalText":true,"sourceStartIndex":102,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Deine Hand hieltest du vom Hort?","translation":"Did you hold your hand from the orphanage?","literalText":true,"sourceStartIndex":103,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Wen ich liebe, lass' ich für sich gewähren;\ner steh' oder fall', sein Herr ist er:\nHelden nur können mir frommen.","translation":"Those I love, I let be themselves;\nWhether he stands or falls, he is his master:\nOnly heroes can be of service to me.","literalText":true,"sourceStartIndex":104,"sourceLineCount":3},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Mit Mime räng' ich allein um den Ring?","translation":"Am I alone with Mime fighting for the ring?","literalText":true,"sourceStartIndex":107,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Ausser dir begehrt er einzig das Gold.","translation":"Besides you, he desires only gold.","literalText":true,"sourceStartIndex":108,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Und dennoch gewänn' ich ihn nicht?","translation":"And yet I wouldn't win him?","literalText":true,"sourceStartIndex":109,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ruhig nähertretend","translation":"quietly approaching","literalText":true,"sourceStartIndex":110,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Ein Helde naht, den Hort zu befrei'n;\nzwei Niblungen geizen das Gold;\nFafner fällt, der den Ring bewacht:\nwer ihn rafft, hat ihn gewonnen.\nWillst du noch mehr?\nDort liegt der Wurm:","translation":"A hero is approaching to free the hoard;\nTwo Nibelungs are stingy with gold;\nFafner, who guards the ring, falls:\nWhoever grasps it has won it.\nDo you want more?\nThat's where the problem lies:","literalText":true,"sourceStartIndex":111,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er wendet sich nach der Höhle","translation":"he turns towards the cave","literalText":true,"sourceStartIndex":117,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"warnst du ihn vor dem Tod,\nwillig wohl liess' er den Tand.\nIch selber weck' ihn dir auf.","translation":"Are you warning him about death?\nHe willingly let go of the trinkets.\nI'll wake him up for you myself.","literalText":true,"sourceStartIndex":118,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er stellt sich auf die Anhöhe vor der Höhle und ruft hinein","translation":"He stands on the hill in front of the cave and shouts inside.","literalText":true,"sourceStartIndex":121,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Fafner! Fafner!\nErwache, Wurm!","translation":"Fafner! Fafner!\nWake up, worm!","literalText":true,"sourceStartIndex":122,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in gespanntem Erstaunen, für sich","translation":"in tense astonishment, for himself","literalText":true,"sourceStartIndex":124,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Was beginnt der Wilde?\nGönnt er mir's wirklich?","translation":"What does the savage begin?\nDoes he really want me to have it?","literalText":true,"sourceStartIndex":125,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Aus der finstern Tiefe des Hintergrundes hört man Fafners Stimme durch ein starkes Sprachrohr","translation":"From the dark depths of the background, Fafner's voice can be heard through a powerful speaking tube.","literalText":true,"sourceStartIndex":127,"sourceLineCount":1},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Wer stört mir den Schlaf?","translation":"Who is disturbing my sleep?","literalText":true,"sourceStartIndex":128,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"der Höhle zugewandt","translation":"facing the cave","literalText":true,"sourceStartIndex":129,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Gekommen ist einer,\nNot dir zu künden:\ner lohnt dir's mit dem Leben,\nlohnst du das Leben ihm\nmit dem Horte, den du hütest?","translation":"One of them came,\nI have to inform you:\nHe will reward you with his life,\nAre you worth his life?\nwith the hoard you are guarding?","literalText":true,"sourceStartIndex":130,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er beugt sein Ohr lauschend der Höhle zu","translation":"He bends his ear towards the cave, listening intently.","literalText":true,"sourceStartIndex":135,"sourceLineCount":1},{"speaker":"FAFNERS STIMME","speakerTranslation":"FAFNERS STIMME","original":"Was will er?","translation":"What does he want?","literalText":true,"sourceStartIndex":136,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ist dem Wanderer zur Seite getreten und ruft in die Höhle","translation":"stepped aside to help the hiker and called into the cave.","literalText":true,"sourceStartIndex":137,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Wache, Fafner! Wache, du Wurm!","translatedTitle":"Guard, Fafner! Guard, you worm!","participants":["ALBERICH","FAFNERS STIMME","WANDERER"],"sourceStartIndex":138,"sourceLineCount":37,"turns":[{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Wache, Fafner! Wache, du Wurm!\nEin starker Helde naht,\ndich heil'gen will er bestehn.","translation":"Guard, Fafner! Guard, you worm!\nA powerful hero is approaching,\nHe wants to preserve you, to sanctify you.","literalText":true,"sourceStartIndex":138,"sourceLineCount":3},{"speaker":"FAFNERS STIMME","speakerTranslation":"FAFNERS STIMME","original":"Mich hungert sein.","translation":"I am hungry.","literalText":true,"sourceStartIndex":141,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Kühn ist des Kindes Kraft,\nscharf schneidet sein Schwert.","translation":"Bold is the child's strength,\nHis sword cuts sharply.","literalText":true,"sourceStartIndex":142,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Den goldnen Reif geizt er allein:\nlass mir den Ring zum Lohn,\nso wend' ich den Streit;\ndu wahrest den Hort,\nund ruhig lebst du lang'!","translation":"He is stingy with the golden hoop alone:\nLet me have the ring as a reward,\nThat's how I turn the tide of the argument;\nYou protect the refuge,\nand you will live long in peace!","literalText":true,"sourceStartIndex":144,"sourceLineCount":5},{"speaker":"FAFNERS STIMME","speakerTranslation":"FAFNERS STIMME","original":"Ich lieg' und besitz',","translation":"I lie and possess,","literalText":true,"sourceStartIndex":149,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"gähnend","translation":"yawning","literalText":true,"sourceStartIndex":150,"sourceLineCount":1},{"speaker":"FAFNERS STIMME","speakerTranslation":"FAFNERS STIMME","original":"lasst mich schlafen!","translation":"Let me sleep!","literalText":true,"sourceStartIndex":151,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lacht auf und wendet sich dann wieder zu Alberich","translation":"laughs and then turns back to Alberich","literalText":true,"sourceStartIndex":152,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Nun, Alberich, das schlug fehl.\nDoch schilt mich nicht mehr Schelm!\nDies eine, rat' ich, achte noch wohl:","translation":"Well, Alberich, that failed.\nBut don't call me a scoundrel anymore!\nThis one thing, I advise, you should still pay close attention to:","literalText":true,"sourceStartIndex":153,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"vertraulich zum ihm tretend","translation":"approaching him confidentially","literalText":true,"sourceStartIndex":156,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Alles ist nach seiner Art,\nan ihr wirst du nichts ändern.\nIch lass' dir die Stätte, stelle dich fest!\nVersuch's mit Mime, dem Bruder,\nder Art ja versiehst du dich besser.","translation":"Everything is according to its own nature,\nYou won't change anything about her.\nI'll leave you the place, establish yourself!\nTry Mime, the brother,\nYou'd better understand that kind of thing.","literalText":true,"sourceStartIndex":157,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zum Abgange gewendet","translation":"turned towards departure","literalText":true,"sourceStartIndex":162,"sourceLineCount":1},{"speaker":"WANDERER","speakerTranslation":"WANDERER","original":"Was anders ist, das lerne nun auch!","translation":"Learn what is different!","literalText":true,"sourceStartIndex":163,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er verschwindet im Walde. Sturmwind erhebt sich, heller Glanz bricht aus; dann vergeht beides schnell\nblickt dem davonjagenden Wanderer nach","translation":"He disappears into the forest. A storm wind rises, a bright blaze bursts forth; then both quickly vanish.\nwatches the fleeing hiker","literalText":true,"sourceStartIndex":164,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Da reitet er hin, auf lichtem Ross;\nmich lässt er in Sorg' und Spott.\nDoch lacht nur zu,\nihr leichtsinniges, lustgieriges Göttergelichter!\nEuch seh' ich noch alle vergehn!\nSolang' das Gold am Lichte glänzt,\nhält ein Wissender Wacht.\nTrügen wird euch sein Trotz!","translation":"There he rides, on a bright horse;\nHe leaves me in sorrow and ridicule.\nGo ahead and laugh,\nYou reckless, pleasure-seeking gods!\nI see you all perish!\nAs long as the gold shines in the light,\nA wise man keeps watch.\nHis defiance will deceive you!","literalText":true,"sourceStartIndex":166,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er schlüpft zur Seite in das Geklüft. Die Bühne bleibt leer. Morgendämmerung","translation":"He slips sideways into the crevice. The stage remains empty. Dawn.","literalText":true,"sourceStartIndex":174,"sourceLineCount":1}]}]},{"number":2,"originalHeading":"ZWEITE SZENE","translatedHeading":"Second Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Wir sind zur Stelle! Bleib hier stehn!","translatedTitle":"We're here! Stay right here!","participants":["MIME","SIEGFRIED"],"sourceStartIndex":0,"sourceLineCount":69,"turns":[{"speaker":"MIME","speakerTranslation":"MIME","original":"Wir sind zur Stelle! Bleib hier stehn!","translation":"We're here! Stay right here!","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"setzt sich unter einer grossen Linde nieder und schaut sich um","translation":"sits down under a large linden tree and looks around.","literalText":true,"sourceStartIndex":1,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hier soll ich das Fürchten lernen?\nFern hast du mich geleitet:\neine volle Nacht im Walde\nselbander wanderten wir.\nNun sollst du, Mime, mich meiden!\nLern' ich hier nicht,\nwas ich lernen soll,\nallein zieh' ich dann weiter:\ndich endlich werd' ich da los!","translation":"I'm supposed to learn to be afraid here?\nYou led me from afar:\na full night in the woods\nWe hiked alone.\nNow you, Mime, should avoid me!\nI won't learn anything here,\nwhat I should learn\nI'll continue on alone:\nI'll finally get rid of you!","literalText":true,"sourceStartIndex":2,"sourceLineCount":9},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"setzt sich ihm gegenüber, so dass er die Höhle immer noch im Auge behält","translation":"sits down opposite him, so that he can still keep an eye on the cave.","literalText":true,"sourceStartIndex":11,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Glaube, Liebster!\nLernst du heut' und hier das Fürchten nicht,\nan andrem Ort, zu andrer Zeit\nschwerlich erfährst du's je.\nSiehst du dort den dunklen Höhlenschlund?\nDarin wohnt ein greulich wilder Wurm:\nunmassen grimmig ist er und gross;\nein schrecklicher Rachen reisst sich ihm auf;\nmit Haut und Haar auf einen Happ\nverschlingt der Schlimme dich wohl.","translation":"Believe, dearest!\nIf you don't learn to be afraid today and here,\nin another place, at another time\nYou'll probably never find out.\nDo you see the dark cave entrance there?\nA horribly wild worm lives inside:\nHe is immensely grim and large;\nA terrible jaw opens up on him;\nskin and hair in one bite\nThe Evil One will surely devour you.","literalText":true,"sourceStartIndex":12,"sourceLineCount":10},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"immer unter der Linde sitzend","translation":"always sitting under the linden tree","literalText":true,"sourceStartIndex":22,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Gut ist's, den Schlund ihm zu schliessen:\ndrum biet' ich mich nicht dem Gebiss.","translation":"It's good to close his mouth:\nTherefore, I do not offer myself to the dentures.","literalText":true,"sourceStartIndex":23,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Giftig giesst sich ein Geifer ihm aus:\nwen mit des Speichels Schweiss er bespeit,\ndem schwinden wohl Fleisch und Gebein.","translation":"A poisonous drool poured out of him:\nwhom he spits with saliva and sweat,\nHis flesh and bones are probably wasting away.","literalText":true,"sourceStartIndex":25,"sourceLineCount":3},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Dass des Geifers Gift mich nicht sehre,\nweich' ich zur Seite dem Wurm.","translation":"That the venom of the spittle does not harm me,\nI move aside to avoid the worm.","literalText":true,"sourceStartIndex":28,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Ein Schlangenschweif schlägt sich ihm auf:\nwen er damit umschlingt und fest umschliesst,\ndem brechen die Glieder wie Glas!","translation":"A snake's tail spreads across his body:\nwhom he embraces and tightly encloses with it,\nHis limbs will break like glass!","literalText":true,"sourceStartIndex":30,"sourceLineCount":3},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Vor des Schweifes Schwang mich zu wahren,\nhalt' ich den Argen im Aug'.\nDoch heisse mich das:\nhat der Wurm ein Herz?","translation":"Before the tail swung me to guard,\nI'll keep an eye on the bad guys.\nBut let me be called by that:\nDoes the worm have a heart?","literalText":true,"sourceStartIndex":33,"sourceLineCount":4},{"speaker":"MIME","speakerTranslation":"MIME","original":"Ein grimmiges, hartes Herz!","translation":"A grim, hard heart!","literalText":true,"sourceStartIndex":37,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Das sitzt ihm doch,\nwo es jedem schlägt,\ntrag' es Mann oder Tier?","translation":"That really suits him.\nwhere it beats everyone\nWill it be worn by a man or an animal?","literalText":true,"sourceStartIndex":38,"sourceLineCount":3},{"speaker":"MIME","speakerTranslation":"MIME","original":"Gewiss, Knabe, da führt's auch der Wurm.\nJetzt kommt dir das Fürchten wohl an?","translation":"Certainly, boy, even the worm leads the way.\nNow you're starting to feel scared, aren't you?","literalText":true,"sourceStartIndex":41,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"bisher nachlässig ausgestreckt, erhebt sich rasch zum Sitz","translation":"Having been carelessly stretched out until now, he quickly rises to a seat.","literalText":true,"sourceStartIndex":43,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Notung stoss' ich dem Stolzen ins Herz!\nSoll das etwa Fürchten heissen?\nHe, du Alter! Ist das alles,\nwas deine List mich lehren kann?\nFahr' deines Wegs dann weiter;\ndas Fürchten lern' ich hier nicht.","translation":"Nothung, I'll thrust it into the proud man's heart!\nDoes that mean fear?\nHey, you old man! Is that all?\nWhat can your cunning teach me?\nThen continue on your way;\nI won't learn to be afraid here.","literalText":true,"sourceStartIndex":44,"sourceLineCount":6},{"speaker":"MIME","speakerTranslation":"MIME","original":"Wart' es nur ab!\nWas ich dir sage, dünke dich tauber Schall:\nihn selber musst du hören und sehn,\ndie Sinne vergehn dir dann schon!\nWenn dein Blick verschwimmt,\nder Boden dir schwankt,\nim Busen bang dein Herz erbebt:","translation":"Just you wait!\nWhat I say to you may seem like deaf sound:\nYou have to hear and see him yourself.\nYour senses will be completely lost!\nWhen your vision blurs,\nthe ground beneath you is swaying,\nYour heart trembles in your breast with fear:","literalText":true,"sourceStartIndex":50,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sehr freundlich","translation":"very friendly","literalText":true,"sourceStartIndex":57,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"dann dankst du mir, der dich führte,\ngedenkst, wie Mime dich liebt.","translation":"Then you will thank me, who guided you.\nRemember how Mime loves you.","literalText":true,"sourceStartIndex":58,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Du sollst mich nicht lieben!\nSagt' ich dir's nicht?\nFort aus den Augen mir!\nLass mich allein:\nsonst halt' ich's hier länger nicht aus,\nfängst du von Liebe gar an!\nDas eklige Nicken und Augenzwicken,\nwann endlich soll ich's nicht mehr sehn,\nwann werd' ich den Albernen los?","translation":"You shall not love me!\nDidn't I tell you?\nGet out of my sight!\nLeave me alone:\nOtherwise I won't be able to stand it here much longer.\nAnd you're not even going to start on love!\nThe disgusting nodding and eye-pinching,\nWhen will I finally no longer have to see it?\nWhen will I get rid of this silly guy?","literalText":true,"sourceStartIndex":60,"sourceLineCount":9}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Ich lass' dich schon.","translatedTitle":"I'll let you go.","participants":["MIME","SIEGFRIED"],"sourceStartIndex":69,"sourceLineCount":72,"turns":[{"speaker":"MIME","speakerTranslation":"MIME","original":"Ich lass' dich schon.\nAm Quell dort lagr' ich mich;\nsteh' du nur hier;\nsteigt dann die Sonne zur Höh',\nmerk' auf den Wurm:\naus der Höhle wälzt er sich her,\nhier vorbei biegt er dann,\nam Brunnen sich zu tränken.","translation":"I'll let you go.\nI lay down by the spring;\nJust stand here;\nWhen the sun rises to its highest point,\nPay attention to the worm:\nHe rolls out of the cave,\nHe then turns past here,\nto drink at the fountain.","literalText":true,"sourceStartIndex":69,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lachend","translation":"laughing","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mime, weilst du am Quell,\ndahin lass' ich den Wurm wohl gehn:\nNotung stoss' ich ihm erst in die Nieren,\nwenn er dich selbst dort mit weggesoffen.\nDarum, hör' meinen Rat,\nraste nicht dort am Quell;\nkehre dich weg, so weit du kannst,\nund komm' nie mehr zu mir!","translation":"Mime, if you dwell at the source,\nI'll let the worm go there:\nI'll first thrust Nothung into his kidneys,\nif he drank you away there too.\nTherefore, listen to my advice,\nDo not rest there at the spring;\nTurn away as far as you can,\nand never come back to me!","literalText":true,"sourceStartIndex":78,"sourceLineCount":8},{"speaker":"MIME","speakerTranslation":"MIME","original":"Nach freislichem Streit dich zu erfrischen,\nwirst du mir wohl nicht wehren?","translation":"To refresh yourself after a free argument,\nYou won't resist me, will you?","literalText":true,"sourceStartIndex":86,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried wehrt ihn hastig ab","translation":"Siegfried hastily fends him off.","literalText":true,"sourceStartIndex":88,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Rufe mich auch,\ndarbst du des Rates,","translation":"Call me too,\ndo you lack the advice?","literalText":true,"sourceStartIndex":89,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried wiederholt die Gebärde mit Ungestüm","translation":"Siegfried repeats the gesture impetuously.","literalText":true,"sourceStartIndex":91,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"oder wenn dir das Fürchten gefällt.","translation":"Or if you enjoy being scared.","literalText":true,"sourceStartIndex":92,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried erhebt sich und treibt Mime mit wütender Gebärde zum Fortgehen\nim Abgehen für sich","translation":"Siegfried rises and, with an angry gesture, urges Mime to leave.\nin leaving for oneself","literalText":true,"sourceStartIndex":93,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Fafner und Siegfried - Siegfried und Fafner -\nO brächten beide sich um!","translation":"Fafner and Siegfried - Siegfried and Fafner -\nOh, if they both killed themselves!","literalText":true,"sourceStartIndex":95,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er verschwindet rechts im Wald\nstreckt sich behaglich unter der Linde aus und blickt dem davongehenden Mime nach","translation":"He disappears into the woods to the right.\nShe stretches out comfortably under the linden tree and watches the departing mime.","literalText":true,"sourceStartIndex":97,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Dass der mein Vater nicht ist,\nwie fühl' ich mich drob so froh!\nNun erst gefällt mir der frische Wald;\nnun erst lacht mir der lustige Tag,\nda der Garstige von mir schied\nund ich gar nicht ihn wiederseh'!","translation":"That he is not my father,\nHow happy I feel about that!\nNow I finally like the fresh forest;\nNow the fun day is finally smiling on me,\nwhen the nasty one left me\nand I never see him again!","literalText":true,"sourceStartIndex":99,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er verfällt in schweigendes Sinnen","translation":"He falls into silent contemplation.","literalText":true,"sourceStartIndex":105,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Wie sah mein Vater wohl aus? -\nHa, gewiss wie ich selbst!\nDenn wär' wo von Mime ein Sohn,\nmüsst' er nicht ganz Mime gleichen?\nGrade so garstig, griesig und grau,\nklein und krumm, höckrig und hinkend,\nmit hängenden Ohren, triefigen Augen -\nfort mit dem Alp!\nIch mag ihn nicht mehr seh'n.","translation":"What did my father look like?\nHa, certainly just like me!\nFor if Mime had a son,\nShouldn't he be exactly like Mime?\nJust so nasty, gritty and grey,\nsmall and crooked, bumpy and limping,\nwith droopy ears, watery eyes -\nAway with the Alp!\nI don't want to see him anymore.","literalText":true,"sourceStartIndex":106,"sourceLineCount":9},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er lehnt sich tiefer zurück und blickt durch die Baumwipfel auf. Tiefe Stille\nWaldweben","translation":"He leans back further and looks up through the treetops. Deep silence.\nForest Weaving","literalText":true,"sourceStartIndex":115,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Aber - wie sah meine Mutter wohl aus?\nDas kann ich nun gar nicht mir denken!\nDer Rehhindin gleich glänzten gewiss\nihr hell schimmernde Augen,\nnur noch viel schöner!\nDa bang sie mich geboren,\nwarum aber starb sie da?\nSterben die Menschenmütter\nan ihren Söhnen alle dahin?\nTraurig wäre das, traun!\nAch, möcht' ich Sohn meine Mutter sehen!\nMeine Mutter - ein Menschenweib!","translation":"But – what did my mother look like?\nI simply cannot imagine that!\nThey certainly shone like the doe.\nher bright, shimmering eyes,\nonly even more beautiful!\nThat's when she gave birth to me,\nBut why did she die there?\nDo human mothers die?\nDid all their sons die?\nThat would be sad, Traun!\nOh, how I wish I could see my mother!\nMy mother - a human woman!","literalText":true,"sourceStartIndex":117,"sourceLineCount":12},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er seufzt leise und streckt sich tiefer zurück. Grosse Stille. Wachsendes Waldweben. Siegfrieds Aufmerksamkeit wird endlich durch den Gesang der Waldvögel gefesselt. Er lauscht mit wachsender Teilnahme einem Waldvogel in den Zweigen über ihm","translation":"He sighed softly and stretched back further. A great silence. A growing murmur of the forest. Siegfried's attention was finally captured by the song of the forest birds. He listened with growing interest to a forest bird in the branches above him.","literalText":true,"sourceStartIndex":129,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Du holdes Vöglein!\nDich hört' ich noch nie:\nbist du im Wald hier daheim?\nVerstünd' ich sein süsses Stammeln!\nGewiss sagt' es mir was,\nvielleicht von der lieben Mutter?\nEin zankender Zwerg hat mir erzählt,\nder Vöglein Stammeln gut zu verstehn,\ndazu könnte man kommen.\nWie das wohl möglich wär'?","translation":"You lovely little bird!\nI've never heard of you before:\nAre you at home in the forest here?\nIf only I could understand his sweet stammering!\nIt certainly means something to me,\nPerhaps from your dear mother?\nA quarrelsome dwarf told me,\nThe stammering of the little birds is easy to understand,\nThat's a possibility.\nHow could that possibly be possible?","literalText":true,"sourceStartIndex":130,"sourceLineCount":10},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er sinnt nach. Sein Blick fällt auf ein Rohrgebüsch unweit der Linde","translation":"He is lost in thought. His gaze falls upon a thicket of reeds not far from the linden tree.","literalText":true,"sourceStartIndex":140,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Hei! Ich versuch's; sing' ihm nach:","translatedTitle":"Hey! I'll give it a try; sing along to him:","participants":["SIEGFRIED","FAFNER"],"sourceStartIndex":141,"sourceLineCount":72,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hei! Ich versuch's; sing' ihm nach:\nauf dem Rohr tön' ich ihm ähnlich!\nEntrat' ich der Worte, achte der Weise,\nsing' ich so seine Sprache,\nversteh' ich wohl auch, was es spricht.","translation":"Hey! I'll give it a try; sing along to him:\nOn the pipe I sound similar to him!\nIf I forgo words, heed the wise man,\nI sing his language like this,\nI guess I understand what it's saying.","literalText":true,"sourceStartIndex":141,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er eilt an den nahen Quell, schneidet mit dem Schwerte ein Rohr ab und schnitzt sich hastig eine Pfeife daraus. Währenddem lauscht er wieder","translation":"He hurries to the nearby spring, cuts off a reed with his sword, and hastily carves himself a pipe from it. Meanwhile, he listens again.","literalText":true,"sourceStartIndex":146,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Es schweigt und lauscht:\nso schwatz' ich denn los!","translation":"It remains silent and listens:\nSo, let me start chatting!","literalText":true,"sourceStartIndex":147,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er bläst auf dem Rohr. Er setzt ab, schnitzt wieder und bessert. Er bläst wieder. Er schüttelt mit dem Kopfe und bessert wieder. Er wird ärgerlich, drückt das Rohr mit der Hand und versucht wieder. Er setzt lächelnd ganz ab","translation":"He blows on the pipe. He stops, carves again, and makes improvements. He blows again. He shakes his head and makes improvements again. He gets annoyed, squeezes the pipe with his hand, and tries again. He stops completely, smiling.","literalText":true,"sourceStartIndex":149,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Das tönt nicht recht;\nauf dem Rohre taugt\ndie wonnige Weise mir nicht.\nVöglein, mich dünkt, ich bleibe dumm:\nvon dir lernt sich's nicht leicht!","translation":"That doesn't sound right;\non the pipes\nThe blissful way is not for me.\nLittle bird, I think I'll remain stupid:\nIt's not easy to learn from you!","literalText":true,"sourceStartIndex":150,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er hört den Vogel wieder und blickt zu ihm auf","translation":"He hears the bird again and looks up at it.","literalText":true,"sourceStartIndex":155,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Nun schäm' ich mich gar\nvor dem schelmischen Lauscher:\ner lugt und kann nichts erlauschen.\nHeida! So höre nun auf mein Horn.","translation":"Now I'm actually ashamed\nbefore the mischievous eavesdropper:\nHe peeks but can't overhear anything.\nHey! Now listen to my horn.","literalText":true,"sourceStartIndex":156,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er schwingt das Rohr und wirft es weit fort","translation":"He swings the pipe and throws it far away.","literalText":true,"sourceStartIndex":160,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Auf dem dummen Rohre gerät mir nichts.\nEiner Waldweise, wie ich sie kann,\nder lustigen sollst du nun lauschen.\nNach liebem Gesellen lockt' ich mit ihr:\nnichts Bessres kam noch als Wolf und Bär.\nNun lass mich sehn,\nwen jetzt sie mir lockt:\nob das mir ein lieber Gesell?","translation":"Nothing will happen to me on that stupid pipe.\nA forest way, as I know it,\nNow you should listen to the funny one.\nI lured her with my dear companion:\nNothing better came along than the wolf and the bear.\nNow let me see,\nwho she is now trying to lure me with:\nIs he a kind companion?","literalText":true,"sourceStartIndex":161,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er nimmt das silberne Hifthorn und bläst darauf. Im Hintergrunde regt es sich. Fafner, in der Gestalt eines ungeheuren eidechsenartigen Schlangenwurmes, hat sich in der Höhle von seinem Lager erhoben; er bricht durch das Gesträuch und wälzt sich aus der Tiefe nach der höheren Stelle vor, so dass er mit dem Vorderleibe bereits auf ihr angelangt ist, als er jetzt einen starken, gähnenden Laut ausstösst\nsieht sich um und heftet den Blick verwundert auf Fafner","translation":"He takes the silver hunting horn and blows it. In the background, there is a stir. Fafner, in the form of a monstrous, lizard-like serpent-worm, has risen from his bed in the cave; he breaks through the undergrowth and rolls himself from the depths toward the higher ground, so that his forebody is already upon it, when he now lets out a loud, yawning sound.\nlooks around and fixes his gaze in surprise on Fafner","literalText":true,"sourceStartIndex":169,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Haha! Da hätte mein Lied\nmir was Liebes erblasen!\nDu wärst mir ein saub'rer Gesell!","translation":"Haha! My song would have been perfect there.\nBlow me something lovely!\nYou would be a fine fellow!","literalText":true,"sourceStartIndex":171,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"hat beim Anblick Siegfrieds auf der Höhe angehalten und verweilt nun daselbst","translation":"He stopped at the sight of Siegfried on the hilltop and is now staying there.","literalText":true,"sourceStartIndex":174,"sourceLineCount":1},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Was ist da?","translation":"What's there?","literalText":true,"sourceStartIndex":175,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ei, bist du ein Tier,\ndas zum Sprechen taugt,\nwohl liess' sich von dir was lernen?\nHier kennt einer das Fürchten nicht:\nkann er's von dir erfahren?","translation":"Hey, are you an animal?\nthat is suitable for speaking,\nI suppose there was something I could learn from you?\nHere is someone who knows no fear:\nCan he find out from you?","literalText":true,"sourceStartIndex":176,"sourceLineCount":5},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Hast du Übermut?","translation":"Are you overconfident?","literalText":true,"sourceStartIndex":181,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mut oder Übermut, was weiss ich!\nDoch dir fahr' ich zu Leibe,\nlehrst du das Fürchten mich nicht!","translation":"Courage or recklessness, what do I know!\nBut I'll attack you,\nYou will not teach me fear!","literalText":true,"sourceStartIndex":182,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"stösst einen lachenden Laut aus","translation":"emits a laughing sound","literalText":true,"sourceStartIndex":185,"sourceLineCount":1},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Trinken wollt' ich:\nnun treff' ich auch Frass!","translation":"I wanted to drink:\nNow I've finally found some food!","literalText":true,"sourceStartIndex":186,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er öffnet seinen Rachen und zeigt die Zähne","translation":"He opens his throat and shows his teeth.","literalText":true,"sourceStartIndex":188,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Eine zierliche Fresse zeigst du mir da,\nlachende Zähne im Leckermaul!\nGut wär' es, den Schlund dir zu schliessen;\ndein Rachen reckt sich zu weit!","translation":"You're showing me a delicate face there,\nLaughing teeth in a sweet tooth!\nIt would be good to close your throat;\nYour throat is sticking out too far!","literalText":true,"sourceStartIndex":189,"sourceLineCount":4},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Zu tauben Reden taugt er schlecht:\ndich zu verschlingen, frommt der Schlund.","translation":"He's not good at making deaf speeches:\nThe maw is good for devouring you.","literalText":true,"sourceStartIndex":193,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er droht mit dem Schweife","translation":"He threatens with his tail","literalText":true,"sourceStartIndex":195,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hoho! Du grausam grimmiger Kerl!\nVon dir verdaut sein, dünkt mich übel:\nrätlich und fromm doch scheint's,\ndu verrecktest hier ohne Frist.","translation":"Hoho! You cruel, grim fellow!\nTo be digested by you seems nauseating to me:\nYet it seems, prudent and pious,\nYou'll die here without a time limit.","literalText":true,"sourceStartIndex":196,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"brüllend","translation":"roaring","literalText":true,"sourceStartIndex":200,"sourceLineCount":1},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Pruh! Komm, prahlendes Kind!","translation":"Pruh! Come on, boastful child!","literalText":true,"sourceStartIndex":201,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hab' acht, Brüller! Der Prahler naht!","translation":"Watch out, roarer! The braggart is approaching!","literalText":true,"sourceStartIndex":202,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er zieht sein Schwert, springt Fafner an und bleibt herausfordernd stehen. Fafner wälzt sich weiter auf die Höhe herauf und sprüht aus den Nüstern auf Siegfried. Dieser weicht dem Geifer aus, springt näher zu und stellt sich zur Seite. Fafner sucht ihn mit dem Schweife zu erreichen. Siegfried, welchen Fafner fast erreicht hat, springt mit einem Satze über diesen hinweg und verwundet ihn an dem Schweife. Fafner brüllt, zieht den Schweif heftig zurück und bäumt den Vorderleib, um mit dessen voller Wucht sich auf Siegfried zu werfen; so bietet er diesem die Brust dar; Siegfried erspäht schnell die Stelle des Herzens und stösst sein Schwert bis an das Heft hinein. Fafner bäumt sich vor Schmerz noch höher und sinkt, als Siegfried das Schwert losgelassen und zur Seite gesprungen ist, auf die Wunde zusammen","translation":"He draws his sword, leaps at Fafner, and stands defiantly still. Fafner continues to roll up the hillside, spraying saliva at Siegfried. Siegfried dodges the spittle, leaps closer, and steps aside. Fafner tries to reach him with his tail. Siegfried, whom Fafner has almost reached, leaps over him in one bound and wounds him with the tail. Fafner roars, violently pulls back his tail, and rears up his forequarters, using them to throw himself upon Siegfried with full force, thus exposing his chest. Siegfried quickly spots the heart and plunges his sword in to the hilt. Fafner rears up even higher in pain and, when Siegfried releases the sword and leaps aside, collapses onto the wound.","literalText":true,"sourceStartIndex":203,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Da lieg', neidischer Kerl!\nNotung trägst du im Herzen.","translation":"There you lie, you envious fellow!\nYou carry Nothung in your heart.","literalText":true,"sourceStartIndex":204,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit schwächerer Stimme","translation":"with a weaker voice","literalText":true,"sourceStartIndex":206,"sourceLineCount":1},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Wer bist du, kühner Knabe,\nder das Herz mir traf?\nWer reizte des Kindes Mut\nzu der mordlichen Tat?\nDein Hirn brütete nicht,\nwas du vollbracht.","translation":"Who are you, bold boy?\nthe one that touched my heart?\nWho provoked the child's courage\nto the murderous act?\nYour brain wasn't brooding,\nwhat you accomplished.","literalText":true,"sourceStartIndex":207,"sourceLineCount":6}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Viel weiss ich noch nicht,","translatedTitle":"I don't know much yet.","participants":["SIEGFRIED","FAFNER","STIMME EINES WALDVOGELS"],"sourceStartIndex":213,"sourceLineCount":46,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Viel weiss ich noch nicht,\nnoch nicht auch, wer ich bin.\nMit dir mordlich zu ringen,\nreiztest du selbst meinen Mut.","translation":"I don't know much yet.\nnot yet who I am.\nTo wrestle with you in a murderous struggle,\nYou yourself tempted my courage.","literalText":true,"sourceStartIndex":213,"sourceLineCount":4},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Du helläugiger Knabe, unkund deiner selbst,\nwen du gemordet meld' ich dir.\nDer Riesen ragend Geschlecht,\nFasolt und Fafner,\ndie Brüder - fielen nun beide.\nUm verfluchtes Gold, von Göttern vergabt,\ntraf ich Fasolt zu Tod.\nDer nun als Wurm den Hort bewachte,\nFafner, den letzten Riesen,\nfällte ein rosiger Held.\nBlicke nun hell, blühender Knabe:\nder dich Blinden reizte zur Tat,\nberät jetzt des Blühenden Tod!","translation":"You bright-eyed boy, unaware of yourself,\nIf you murder someone, I'll report you.\nThe giant's towering gender,\nFasolt and Fafner\nThe brothers – both fell.\nCursed gold, bestowed by gods,\nI met Fasolt dead.\nThe one who now guarded the hoard as a worm,\nFafner, the last giant,\nA rosy-cheeked hero fell.\nLook now bright, blooming boy:\nwho incited you, blind man, to action,\nis now advising of the Blooming Death!","literalText":true,"sourceStartIndex":217,"sourceLineCount":13},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ersterbend","translation":"dying","literalText":true,"sourceStartIndex":230,"sourceLineCount":1},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Merk', wie's endet! Acht' auf mich!","translation":"Remember how it ends! Watch out for me!","literalText":true,"sourceStartIndex":231,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Woher ich stamme, rate mir noch;\nweise ja scheinst du, Wilder, im Sterben:\nrat' es nach meinem Namen:\nSiegfried bin ich genannt.","translation":"Guess where I come from;\nWise you seem, Wilder, in your dying moments:\nGuess what my name is:\nMy name is Siegfried.","literalText":true,"sourceStartIndex":232,"sourceLineCount":4},{"speaker":"FAFNER","speakerTranslation":"FAFNER","original":"Siegfried...!","translation":"Siegfried...!","literalText":true,"sourceStartIndex":236,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er seufzt, hebt sich und stirbt","translation":"He sighs, rises, and dies.","literalText":true,"sourceStartIndex":237,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Zur Kunde taugt kein Toter.\nSo leite mich denn mein lebendes Schwert!","translation":"A dead person is no good as a customer.\nSo let my living sword guide me!","literalText":true,"sourceStartIndex":238,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Fafner hat sich im Sterben zur Seite gewälzt. Siegfried zieht ihm jetzt das Schwert aus der Brust: dabei wird seine Hand vom Blute benetzt: er fährt heftig mit der Hand auf","translation":"Fafner rolled to his side as he died. Siegfried now pulls the sword from his chest: his hand is wet with blood; he jerks his hand violently.","literalText":true,"sourceStartIndex":240,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Wie Feuer brennt das Blut!","translation":"Blood burns like fire!","literalText":true,"sourceStartIndex":241,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er führt unwillkürlich die Finger zum Munde, um das Blut von ihnen abzusaugen. Wie er sinnend vor sich hinblickt, wird seine Aufmerksamkeit immer mehr von dem Gesange der Waldvögel angezogen","translation":"He instinctively brings his fingers to his mouth to suck the blood from them. As he gazes thoughtfully ahead, his attention is increasingly drawn to the song of the forest birds.","literalText":true,"sourceStartIndex":242,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ist mir doch fast,\nals sprächen die Vöglein zu mir!\nNützte mir das des Blutes Genuss?\nDas seltne Vöglein hier,\nhorch, was singt es nur?","translation":"I almost feel that way,\nIt was as if the little birds were speaking to me!\nDid the pleasure of blood benefit me?\nThis rare little bird here,\nListen, what is it singing?","literalText":true,"sourceStartIndex":243,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"aus den Zweigen der Linde über Siegfried","translation":"from the branches of the linden tree about Siegfried","literalText":true,"sourceStartIndex":248,"sourceLineCount":1},{"speaker":"STIMME EINES WALDVOGELS","speakerTranslation":"STIMME EINES WALDVOGELS","original":"Hei! Siegfried gehört nun der Niblungen Hort!\nO, fänd' in der Höhle den Hort er jetzt!\nWollt' er den Tarnhelm gewinnen,\nder taugt' ihm zu wonniger Tat:\ndoch möcht' er den Ring sich erraten,\nder macht' ihn zum Walter der Welt!","translation":"Hey! Siegfried now belongs to the Nibelung hoard!\nOh, if only he could find his treasure in the cave now!\nHe wanted to win the Tarnhelm,\nIt suited him for blissful deeds:\nbut he would like to guess the ring,\nThat makes him the Walter of the world!","literalText":true,"sourceStartIndex":249,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"hat mit verhaltenem Atem und verzückter Miene gelauscht","translation":"listened with held breath and a rapturous expression","literalText":true,"sourceStartIndex":255,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Dank, liebes Vöglein, für deinen Rat!\nGern folg' ich dem Ruf!","translation":"Thank you, dear little bird, for your advice!\nI gladly follow the call!","literalText":true,"sourceStartIndex":256,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er wendet sich nach hinten und steigt in die Höhle hinab, wo er alsbald gänzlich verschwindet","translation":"He turns around and descends into the cave, where he soon disappears completely.","literalText":true,"sourceStartIndex":258,"sourceLineCount":1}]}]},{"number":3,"originalHeading":"DRITTE SZENE","translatedHeading":"Third Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Wohin schleichst du eilig und schlau,","translatedTitle":"Where are you sneaking off to, hurried and clever?","participants":["ALBERICH","MIME"],"sourceStartIndex":0,"sourceLineCount":75,"turns":[{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Wohin schleichst du eilig und schlau,\nschlimmer Gesell?","translation":"Where are you sneaking off to, hurried and clever?\nBad fellow?","literalText":true,"sourceStartIndex":0,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Verfluchter Bruder, dich braucht' ich hier!\nWas bringt dich her?","translation":"Damned brother, I needed you here!\nWhat brings you here?","literalText":true,"sourceStartIndex":2,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Geizt es dich, Schelm, nach meinem Gold?\nVerlangst du mein Gut?","translation":"Are you stingy with my gold, you scoundrel?\nDo you demand my property?","literalText":true,"sourceStartIndex":4,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Fort von der Stelle! Die Stätte ist mein:\nwas stöberst du hier?","translation":"Away from this spot! This place is mine!\nWhat are you browsing here?","literalText":true,"sourceStartIndex":6,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Stör' ich dich wohl im stillen Geschäft,\nwenn du hier stiehlst?","translation":"Am I disturbing you in your quiet business?\nWhat if you steal from here?","literalText":true,"sourceStartIndex":8,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Was ich erschwang mit schwerer Müh',\nsoll mir nicht schwinden.","translation":"What I won with great effort,\nIt should not disappear from my life.","literalText":true,"sourceStartIndex":10,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Hast du dem Rhein das Gold zum Ringe geraubt?\nErzeugtest du gar den zähen Zauber im Reif?","translation":"Did you steal the gold from the Rhine to make a ring?\nDid you even create the tenacious magic within the frost?","literalText":true,"sourceStartIndex":12,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Wer schuf den Tarnhelm,\nder die Gestalten tauscht?\nDer seiner bedurfte,\nerdachtest du ihn wohl?","translation":"Who created the Tarnhelm?\nwho exchanges forms?\nHe needed him,\nDid you perhaps invent him?","literalText":true,"sourceStartIndex":14,"sourceLineCount":4},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Was hättest du Stümper\nje wohl zu stampfen verstanden?\nDer Zauberring\nzwang mir den Zwerg erst zur Kunst.","translation":"What would you have done, you bungler?\nDo you think you understand how to stamp?\nThe magic ring\nI first forced the dwarf to do art.","literalText":true,"sourceStartIndex":18,"sourceLineCount":4},{"speaker":"MIME","speakerTranslation":"MIME","original":"Wo hast du den Ring?\nDir Zagem entrissen ihn Riesen!\nWas du verlorst,\nmeine List erlangt es für mich.","translation":"Where did you put the ring?\nYou giants snatched him from you, Zagem!\nWhat you lost,\nMy cunning will achieve it for me.","literalText":true,"sourceStartIndex":22,"sourceLineCount":4},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Mit des Knaben Tat\nwill der Knicker nun knausern?\nDir gehört sie gar nicht,\nder Helle ist selbst ihr Herr!","translation":"With the boy's deed\nIs the penny pincher going to be stingy now?\nIt doesn't even belong to you,\nThe light one is his own master!","literalText":true,"sourceStartIndex":26,"sourceLineCount":4},{"speaker":"MIME","speakerTranslation":"MIME","original":"Ich zog ihn auf;\nfür die Zucht zahlt er mir nun:\nfür Müh' und Last\nerlauert' ich lang meinen Lohn!","translation":"I raised him;\nHe now pays me for the breeding:\nfor toil and burden\nI waited a long time for my reward!","literalText":true,"sourceStartIndex":30,"sourceLineCount":4},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Für des Knaben Zucht\nwill der knickrige schäbige Knecht\nkeck und kühn wohl gar König nun sein?\nDem räudigsten Hund\nwäre der Ring geratner als dir:\nnimmer erringst du Rüpel den Herrscherreif!","translation":"For the boy's upbringing\nwill the miserly, shabby servant\nBold and bold, perhaps even to be king now?\nThe most mangy dog\nThe ring would be more advisable for you than for yourself:\nYou ruffian will never win the crown of rulership!","literalText":true,"sourceStartIndex":34,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"kratzt sich den Kopf","translation":"scratches his head","literalText":true,"sourceStartIndex":40,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Behalt' ihn denn, und hüt' ihn wohl,\nden hellen Reif!\nSei du Herr: doch mich heisse auch Bruder!\nUm meines Tarnhelms lustigen Tand\ntausch' ich ihn dir:\nuns beiden taugt's, teilen die Beute wir so.","translation":"Keep him then, and guard him well,\nthe bright frost!\nBe lord: but call me brother too!\nTo my camouflage helmet's funny trinkets\nI'll exchange it for you:\nWe both like it, so we'll share the spoils.","literalText":true,"sourceStartIndex":41,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er reibt sich zutraulich die Hände\nmit Hohnlachen","translation":"He rubs his hands trustingly.\nwith mocking laughter","literalText":true,"sourceStartIndex":47,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Teilen mit dir?\nUnd den Tarnhelm gar?\nWie schlau du bist!\nSicher schlief' ich\nniemals vor deinen Schlingen!","translation":"Share with you?\nAnd what about the camouflage helmet?\nHow clever you are!\nI slept soundly.\nNever before your snares!","literalText":true,"sourceStartIndex":49,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ausser sich","translation":"beside himself","literalText":true,"sourceStartIndex":54,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Selbst nicht tauschen?\nAuch nicht teilen?\nLeer soll ich gehn?\nGanz ohne Lohn?","translation":"Not even exchanging it yourself?\nNot even sharing?\nShould I go empty-handed?\nCompletely without pay?","literalText":true,"sourceStartIndex":55,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"kreischend","translation":"screeching","literalText":true,"sourceStartIndex":59,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Gar nichts willst du mir lassen?","translation":"You won't leave me anything at all.","literalText":true,"sourceStartIndex":60,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Nichts von allem!\nNicht einen Nagel sollst du dir nehmen!","translation":"None of the above!\nDon't take a single nail!","literalText":true,"sourceStartIndex":61,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in höchster Wut","translation":"in utter fury","literalText":true,"sourceStartIndex":63,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Weder Ring noch Tarnhelm\nsoll dir denn taugen!\nNicht teil' ich nun mehr!\nGegen dich doch ruf' ich Siegfried zu Rat\nund des Recken Schwert;\nder rasche Held,\nder richte, Brüderchen, dich!","translation":"Neither ring nor invisibility helmet\nIt should be suitable for you!\nI will no longer share!\nAgainst you, however, I call upon Siegfried for advice.\nand the warrior's sword;\nthe swift hero,\nThe right one, little brother, you!","literalText":true,"sourceStartIndex":64,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried erscheint im Hintergrund","translation":"Siegfried appears in the background","literalText":true,"sourceStartIndex":71,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Kehre dich um!\nAus der Höhle kommt er daher!","translation":"Turn around!\nHe comes out of the cave!","literalText":true,"sourceStartIndex":72,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sich umblickend","translation":"looking around","literalText":true,"sourceStartIndex":74,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Kindischen Tand erkor er gewiss.","translatedTitle":"He certainly chose childish trinkets.","participants":["MIME","ALBERICH","SIEGFRIED","STIMME DES WALDVOGELS"],"sourceStartIndex":75,"sourceLineCount":75,"turns":[{"speaker":"MIME","speakerTranslation":"MIME","original":"Kindischen Tand erkor er gewiss.","translation":"He certainly chose childish trinkets.","literalText":true,"sourceStartIndex":75,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Den Tarnhelm hält er!","translation":"He's holding the invisibility helmet!","literalText":true,"sourceStartIndex":76,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Doch auch den Ring!","translation":"But also the ring!","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Verflucht! - Den Ring!","translation":"Damn it! - The ring!","literalText":true,"sourceStartIndex":78,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"hämisch lachend","translation":"laughing maliciously","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Lass ihn den Ring dir doch geben!\nIch will ihn mir schon gewinnen.","translation":"Let him give you the ring!\nI definitely want to win him over.","literalText":true,"sourceStartIndex":80,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er schlüpft mit den letzten Worten in den Wald zurück","translation":"With his last words, he slips back into the forest.","literalText":true,"sourceStartIndex":82,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Und doch seinem Herrn\nsoll er allein noch gehören!","translation":"And yet to his Lord\nHe should belong to himself alone!","literalText":true,"sourceStartIndex":83,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er verschwindet im Geklüfte\nSiegfried ist mit Tarnhelm und Ring während des letzteren langsam und sinnend aus der Höhle vorgeschritten: er betrachtet gedankenvoll seine Beute und hält, nahe dem Baume, auf der Höhe des Mittelgrundes wieder an","translation":"He disappears into the crevices.\nSiegfried, wearing his Tarnhelm and ring, slowly and thoughtfully emerged from the cave during the latter: he thoughtfully examined his prey and stopped again near the tree, at the level of the middle ground.","literalText":true,"sourceStartIndex":85,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Was ihr mir nützt, weiss ich nicht;\ndoch nahm ich euch\naus des Horts gehäuftem Gold,\nweil guter Rat mir es riet.\nSo taug' eure Zier als des Tages Zeuge,\nes mahne der Tand,\ndass ich kämpfend Fafner erlegt,\ndoch das Fürchten noch nicht gelernt!","translation":"I don't know what use you are to me;\nbut I took you\nfrom the hoard's accumulated gold,\nbecause good advice told me to.\nSo may your adornment serve as a witness to the day,\nThe trinket serves as a warning,\nthat I killed Fafner in combat\nbut they haven't learned to be afraid yet!","literalText":true,"sourceStartIndex":87,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er steckt den Tarnhelm sich in den Gürtel und den Reif an den Finger. Stillschweigen. Wachsendes Waldweben. Siegfried achtet unwillkürlich wieder des Vogels und lauscht ihm mit verhaltenem Atem","translation":"He tucked the Tarnhelm into his belt and the ring onto his finger. Silence. A growing murmur of the forest. Siegfried involuntarily turned his attention to the bird again and listened to it with hushed breath.","literalText":true,"sourceStartIndex":95,"sourceLineCount":1},{"speaker":"STIMME DES WALDVOGELS","speakerTranslation":"STIMME DES WALDVOGELS","original":"Hei! Siegfried gehört\nnun der Helm und der Ring!\nO, traute er Mime, dem treulosen, nicht!\nHörte Siegfried nur scharf\nauf des Schelmen Heuchlergered'!\nWie sein Herz es meint,\nkann er Mime verstehn:\nso nützt' ihm des Blutes Genuss.","translation":"Hey! Siegfried belongs\nNow the helmet and the ring!\nOh, how he did not trust Mime, the faithless one!\nSiegfried only heard sharply\nOn the rogue's hypocritical talk!\nAs his heart dictates,\nCan he understand Mime?\nThus, the pleasure of blood benefits him.","literalText":true,"sourceStartIndex":96,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfrieds Miene und Gebärde drücken aus, dass er den Sinn des Vogelgesanges wohl vernommen. Er sieht Mime sich nähern und bleibt, ohne sich zu rühren, auf sein Schwert gestützt, beobachtend und in sich geschlossen, in seiner Stellung auf der Anhöhe bis zum Schlusse des folgenden Auftrittes\nschleicht heran und beobachtet vom Vordergrunde aus Siegfried","translation":"Siegfried's expression and gesture convey that he has clearly understood the meaning of the birdsong. He sees Mime approaching and remains, without moving, leaning on his sword, observing and withdrawn, in his position on the hilltop until the end of the following scene.\nSiegfried sneaks up and observes from the foreground.","literalText":true,"sourceStartIndex":104,"sourceLineCount":2},{"speaker":"MIME","speakerTranslation":"MIME","original":"Er sinnt und erwägt der Beute Wert.\nWeilte wohl hier ein weiser Wand'rer,\nschweifte umher, beschwatzte das Kind\nmit list'ger Runen Rat?\nZwiefach schlau sei nun der Zwerg;\ndie listigste Schlinge leg' ich jetzt aus,\ndass ich mit traulichem Truggerede\nbetöre das trotzige Kind.","translation":"He ponders and considers the value of the loot.\nA wise wanderer must have stayed here,\nwandered around, chattering at the child\nwith cunning runic advice?\nThe dwarf is now doubly clever;\nI'm now laying the most cunning trap,\nthat I with comforting deception\nCharm the defiant child.","literalText":true,"sourceStartIndex":106,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er tritt näher an Siegfried heran und bewillkommt diesen mit schmeichelnden Gebärden","translation":"He steps closer to Siegfried and greets him with flattering gestures.","literalText":true,"sourceStartIndex":114,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Willkommen, Siegfried!\nSag', du Kühner, hast du das Fürchten gelernt?","translation":"Welcome, Siegfried!\nTell me, you bold one, have you learned to be afraid?","literalText":true,"sourceStartIndex":115,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Den Lehrer fand ich noch nicht!","translation":"I haven't found the teacher yet!","literalText":true,"sourceStartIndex":117,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Doch den Schlangenwurm,\ndu hast ihn erschlagen?\nDas war doch ein schlimmer Gesell?","translation":"But the snake worm,\nYou killed him?\nWasn't he a bad fellow?","literalText":true,"sourceStartIndex":118,"sourceLineCount":3},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So grimm und tückisch er war,\nsein Tod grämt mich doch schier,\nda viel üblere Schächer\nunerschlagen noch leben!\nDer mich ihn morden hiess,\nden hass' ich mehr als den Wurm!","translation":"As grim and treacherous as he was,\nHis death truly grieves me,\nthere are much worse thieves\nStill alive and unharmed!\nThe one who told me to murder him,\nI hate him more than the worm!","literalText":true,"sourceStartIndex":121,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sehr freundlich","translation":"very friendly","literalText":true,"sourceStartIndex":127,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Nur sachte! Nicht lange\nsiehst du mich mehr:\nzum ew'gen Schlaf\nschliess' ich dir die Augen bald!\nWozu ich dich brauchte,","translation":"Gently! Not for long.\nDo you see me more:\nto eternal sleep\nI'll close your eyes soon!\nWhat I needed you for,","literalText":true,"sourceStartIndex":128,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zärtlich","translation":"tender","literalText":true,"sourceStartIndex":133,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"hast du vollbracht;\njetzt will ich nur noch\ndie Beute dir abgewinnen.\nMich dünkt, das soll mir gelingen;\nzu betören bist du ja leicht!","translation":"have accomplished;\nNow I just want\nto wrest the loot from you.\nI think I should be able to do it;\nYou're so easy to charm!","literalText":true,"sourceStartIndex":134,"sourceLineCount":5},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So sinnst du auf meinen Schaden?","translation":"So you're plotting to harm me?","literalText":true,"sourceStartIndex":139,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"verwundert","translation":"surprised","literalText":true,"sourceStartIndex":140,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Wie sagt' ich denn das? -\nSiegfried! Hör doch, mein Söhnchen!\nDich und deine Art\nhasst' ich immer von Herzen;","translation":"How do I say that?\nSiegfried! Listen, my little son!\nYou and your way\nI always hated it with all my heart;","literalText":true,"sourceStartIndex":141,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zärtlich","translation":"tender","literalText":true,"sourceStartIndex":145,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"aus Liebe erzog ich dich Lästigen nicht:\ndem Horte in Fafners Hut,\ndem Golde galt meine Müh'.","translation":"I did not raise you, troublesome one, out of love:\nthe hoard in Fafner's hat,\nMy efforts were for gold.","literalText":true,"sourceStartIndex":146,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"als verspräche er ihm hübsche Sachen","translation":"as if he were promising him nice things","literalText":true,"sourceStartIndex":149,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Gibst du mir das gutwillig nun nicht,","translatedTitle":"If you don't give it to me willingly,","participants":["MIME","SIEGFRIED"],"sourceStartIndex":150,"sourceLineCount":75,"turns":[{"speaker":"MIME","speakerTranslation":"MIME","original":"Gibst du mir das gutwillig nun nicht,","translation":"If you don't give it to me willingly,","literalText":true,"sourceStartIndex":150,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"als wäre er bereit, sein Leben für ihn zu lassen","translation":"as if he were ready to give his life for him","literalText":true,"sourceStartIndex":151,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Siegfried, mein Sohn,\ndas siehst du wohl selbst,","translation":"Siegfried, my son,\nYou can probably see that for yourself.","literalText":true,"sourceStartIndex":152,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit freundlichem Scherze","translation":"with friendly jokes","literalText":true,"sourceStartIndex":154,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"dein Leben musst du mir lassen!","translation":"You must let me have your life!","literalText":true,"sourceStartIndex":155,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Dass du mich hassest, hör' ich gern:\ndoch auch mein Leben muss ich dir lassen?","translation":"I like hearing that you hate me:\nBut must I also leave my life to you?","literalText":true,"sourceStartIndex":156,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ärgerlich","translation":"annoying","literalText":true,"sourceStartIndex":158,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Das sagt' ich doch nicht?\nDu verstehst mich ja falsch!","translation":"I didn't say that, did I?\nYou're misunderstanding me!","literalText":true,"sourceStartIndex":159,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er sucht sein Fläschchen hervor. Er gibt sich die ersichtlichste Mühe zur Verstellung","translation":"He pulls out his bottle. He makes every obvious effort to disguise himself.","literalText":true,"sourceStartIndex":161,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Sieh', du bist müde von harter Müh';\nbrünstig wohl brennt dir der Leib:\ndich zu erquicken mit queckem Trank\nsäumt' ich Sorgender nicht.\nAls dein Schwert du dir branntest,\nbraut' ich den Sud;\ntrinkst du nun den,\ngewinn' ich dein trautes Schwert,\nund mit ihm Helm und Hort.","translation":"Look, you are tired from hard work;\nYour body burns intensely:\nto refresh you with couch grass drink\nI, the worrier, did not delay.\nWhen you burned your sword,\nI brewed the brew;\nAre you drinking this now?\nIf I win your trusted sword,\nand with him helmet and hoard.","literalText":true,"sourceStartIndex":162,"sourceLineCount":9},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er kichert dazu","translation":"he giggles at that","literalText":true,"sourceStartIndex":171,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So willst du mein Schwert\nund was ich erschwungen,\nRing und Beute, mir rauben?","translation":"So you want my sword\nand what I achieved,\nRing and booty, steal from me?","literalText":true,"sourceStartIndex":172,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"heftig","translation":"violent","literalText":true,"sourceStartIndex":175,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Was du doch falsch mich verstehst!\nStamml' ich, fasl' ich wohl gar?\nDie grösste Mühe geb' ich mir doch,\nmein heimliches Sinnen heuchelnd zu bergen,\nund du dummer Bube deutest alles doch falsch!\nÖffne die Ohren, und vernimm genau:\nHöre, was Mime meint!","translation":"How you misunderstand me!\nAm I stammering, or am I even babbling?\nI'm making every effort,\nto feign concealing my secret thoughts,\nAnd you stupid boy, you're interpreting everything wrong!\nOpen your ears, and listen carefully:\nListen to what Mime has to say!","literalText":true,"sourceStartIndex":176,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wieder sehr freundlich, mit ersichtlicher Mühe","translation":"Very friendly again, with obvious effort.","literalText":true,"sourceStartIndex":183,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Hier nimm und trinke die Labung!\nMein Trank labte dich oft:\ntat'st du wohl unwirsch, stelltest dich arg:\nwas ich dir bot, erbost auch, nahmst du's doch immer.","translation":"Here, take and drink the refreshment!\nMy drink often refreshed you:\nYou probably acted rudely, you made a nasty impression:\nEven though I offered you something, you still took it, though you were furious.","literalText":true,"sourceStartIndex":184,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ohne eine Miene zu verziehen","translation":"without flinching","literalText":true,"sourceStartIndex":188,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Einen guten Trank hätt' ich gern:\nwie hast du diesen gebraut?","translation":"I'd like a good drink:\nHow did you brew this?","literalText":true,"sourceStartIndex":189,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lustig scherzend, als schildere er ihm einen angenehm berauschten Zustand, den ihm der Saft bereiten soll","translation":"jokingly, as if describing to him a pleasantly intoxicated state that the juice was supposed to give him.","literalText":true,"sourceStartIndex":191,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Hei! So trink nur, trau' meiner Kunst!\nIn Nacht und Nebel sinken die Sinne dir bald:\nohne Wach' und Wissen\nstracks streckst du die Glieder.\nLiegst du nun da,\nleicht könnt' ich\ndie Beute nehmen und bergen:\ndoch erwachtest du je,\nnirgends wär' ich sicher vor dir,\nhätt' ich selbst auch den Ring.\nDrum mit dem Schwert,\ndas so scharf du schufst,","translation":"Hey! So drink up, trust my art!\nIn the night and fog, your senses will soon fade:\nwithout wakefulness and knowledge\nYou straighten your limbs.\nAre you lying there now,\nI could easily\nTake and retrieve the loot:\nBut did you ever wake up?\nNowhere would I be safe from you,\nI would have the ring myself.\nTherefore with the sword,\nthat you created so sharply,","literalText":true,"sourceStartIndex":192,"sourceLineCount":12},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit einer Gebärde ausgelassener Lustigkeit","translation":"with a gesture of unrestrained merriment","literalText":true,"sourceStartIndex":204,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"hau' ich dem Kind den Kopf erst ab:\ndann hab' ich mir Ruh' und auch den Ring!","translation":"First I'll cut the child's head off:\nThen I'll have peace and quiet, and the ring too!","literalText":true,"sourceStartIndex":205,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er kichert wieder","translation":"He giggles again","literalText":true,"sourceStartIndex":207,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Im Schlafe willst du mich morden?","translation":"You want to murder me while I sleep?","literalText":true,"sourceStartIndex":208,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wütend ärgerlich","translation":"angry, annoyed","literalText":true,"sourceStartIndex":209,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Was möcht' ich? Sagt' ich denn das?","translation":"What do I want? Did I say that?","literalText":true,"sourceStartIndex":210,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er bemüht sich, den zärtlichsten Ton anzunehmen","translation":"He tries to adopt the most tender tone.","literalText":true,"sourceStartIndex":211,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Ich will dem Kind","translation":"I want to give the child","literalText":true,"sourceStartIndex":212,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit sorglichster Deutlichkeit","translation":"with the utmost clarity","literalText":true,"sourceStartIndex":213,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"nur den Kopf abhau'n!","translation":"Just cut off his head!","literalText":true,"sourceStartIndex":214,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit dem Ausdruck herzlicher Besorgtheit für Siegfrieds Gesundheit","translation":"expressing heartfelt concern for Siegfried's health","literalText":true,"sourceStartIndex":215,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Denn hasste ich dich auch nicht so sehr,\nund hätt' ich des Schimpfs\nund der schändlichen Mühe\nauch nicht so viel zu rächen:","translation":"Even though I didn't hate you that much,\nand had I the insult\nand the shameful effort\nnot that much to avenge either:","literalText":true,"sourceStartIndex":216,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sanft","translation":"soft","literalText":true,"sourceStartIndex":220,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"aus dem Wege dich zu räumen,\ndarf ich doch nicht rasten:\nwie käm' ich sonst anders zur Beute,\nda Alberich auch nach ihr lugt?","translation":"to clear you out of the way,\nI'm not allowed to rest, am I?\nHow else would I get my prey?\nBecause Alberich is also looking at her?","literalText":true,"sourceStartIndex":221,"sourceLineCount":4}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Nun, mein Wälsung! Wolfssohn du!","translatedTitle":"Well, my Wälsung! Wolf son you!","participants":["MIME","SIEGFRIED","STIMME DES WALDVOGELS"],"sourceStartIndex":225,"sourceLineCount":72,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er giesst den Saft in das Trinkhorn und führt dieses Siegfried mit aufdringlicher Gebärde zu","translation":"He pours the juice into the drinking horn and, with an obtrusive gesture, presents it to Siegfried.","literalText":true,"sourceStartIndex":225,"sourceLineCount":1},{"speaker":"MIME","speakerTranslation":"MIME","original":"Nun, mein Wälsung! Wolfssohn du!\nSauf', und würg' dich zu Tod:\nNie tust du mehr 'nen Schluck! Hihihihi!","translation":"Well, my Wälsung! Wolf son you!\nDrink, and choke yourself to death:\nYou'll never take another sip! Hehehehe!","literalText":true,"sourceStartIndex":226,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried holt mit dem Schwert aus. Er führt, wie in einer Anwandlung heftigen Ekels einen jähen Streich nach Mime; dieser stürzt sogleich tot zu Boden. Man hört Alberichs höhnisches Gelächter aus dem Geklüfte","translation":"Siegfried raises his sword. As if in a fit of intense disgust, he delivers a sudden blow to Mime; the latter immediately falls dead to the ground. Alberich's mocking laughter can be heard from the ravine.","literalText":true,"sourceStartIndex":229,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Schmeck' du mein Schwert, ekliger Schwätzer!","translation":"Taste my sword, you disgusting chatterer!","literalText":true,"sourceStartIndex":230,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er henkt, auf den am Boden Liegenden blickend, ruhig sein Schwert wieder ein","translation":"Looking down at the man lying on the ground, he calmly hangs his sword back up.","literalText":true,"sourceStartIndex":231,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Neides Zoll zahlt Notung:\ndazu durft' ich ihn schmieden.","translation":"Neide's toll pays Notung:\nI was allowed to forge it.","literalText":true,"sourceStartIndex":232,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er rafft Mimes Leichnam auf, trägt ihn auf die Anhöhe vor den Eingang der Höhle und wirft ihn dort hinein","translation":"He gathers up Mime's body, carries it to the hill in front of the cave entrance, and throws it inside.","literalText":true,"sourceStartIndex":234,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"In der Höhle hier lieg' auf dem Hort!\nMit zäher List erzieltest du ihn:\njetzt magst du des wonnigen walten!\nEinen guten Wächter geb' ich dir auch,\ndass er vor Dieben dich deckt.","translation":"Lie in the cave here on the hoard!\nYou achieved it through tenacious cunning:\nNow you may reign in blissful bliss!\nI'll give you a good guard too,\nthat he will protect you from thieves.","literalText":true,"sourceStartIndex":235,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er wälzt mit grosser Anstrengung den Leichnam des Wurmes vor den Eingang der Höhle, so dass er diesen ganz damit verstopft","translation":"With great effort, he rolls the worm's corpse in front of the cave entrance, completely blocking it.","literalText":true,"sourceStartIndex":240,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Da lieg' auch du, dunkler Wurm!\nDen gleissenden Hort hüte zugleich\nmit dem beuterührigen Feind:\nso fandet beide ihr nun Ruh'!","translation":"There you lie too, dark worm!\nguard the dazzling treasure at the same time\nwith the predatory enemy:\nSo both of you now found peace!","literalText":true,"sourceStartIndex":241,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er blickt eine Weile sinnend in die Höhle hinab und wendet sich dann langsam, wie ermüdet, in den Vordergrund. Es ist Mittag. Er führt sich die Hand über die Stirn","translation":"He gazes thoughtfully down into the cave for a while, then slowly turns, as if wearily, to the foreground. It is midday. He runs his hand over his forehead.","literalText":true,"sourceStartIndex":245,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Heiss ward mir von der harten Last!\nBrausend jagt mein brünst'ges Blut;\ndie Hand brennt mir am Haupt.\nHoch steht schon die Sonne:\naus lichtem Blau blickt ihr Aug'\nauf den Scheitel steil mir herab.\nLinde Kühlung erkies' ich unter der Linde!","translation":"I got hot from the heavy load!\nMy lustful blood races with a roar;\nMy hand is burning on my head.\nThe sun is already high in the sky:\nHer eye gazes out from a light blue sky.\ndown to the top of my head, a steep drop.\nLinde Kühlung erkest' ich unter der Linde!","literalText":true,"sourceStartIndex":246,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er streckt sich unter der Linde aus und blickt wieder die Zweige hinauf","translation":"He stretches out under the linden tree and looks up at the branches again.","literalText":true,"sourceStartIndex":253,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Noch einmal, liebes Vöglein,\nda wir so lang lästig gestört, -\nlauscht' ich gerne deinem Sange:\nauf dem Zweige seh' ich\nwohlig dich wiegen;\nzwitschernd umschwirren\ndich Brüder und Schwestern,\numschweben dich lustig und lieb!\nDoch ich - bin so allein,\nhab' nicht Brüder noch Schwestern:\nmeine Mutter schwand, mein Vater fiel:\nnie sah sie der Sohn!\nMein einz'ger Gesell war ein garstiger Zwerg;\nGüte zwang","translation":"Once again, dear little bird,\nsince we were bothered for so long, -\nI enjoyed listening to your singing:\nI see on the branch\nrock you gently;\nchirping and buzzing around\nyou brothers and sisters,\nThey will surround you in a fun and loving way!\nBut I am so alone,\nI have neither brothers nor sisters:\nMy mother vanished, my father fell:\nHer son never saw her!\nMy only companion was a nasty dwarf;\nGoodness compulsion","literalText":true,"sourceStartIndex":254,"sourceLineCount":14},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"warm","translation":"warm","literalText":true,"sourceStartIndex":268,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"uns nie zu Liebe;\nlistige Schlingen warf mir der Schlaue;\nnun musst' ich ihn gar erschlagen!","translation":"never for our sake;\nThe cunning one cast cunning traps for me;\nNow I had to kill him!","literalText":true,"sourceStartIndex":269,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er blickt schmerzlich bewegt wieder nach den Zweigen auf","translation":"He looked up at the branches again, visibly moved.","literalText":true,"sourceStartIndex":272,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Freundliches Vöglein, dich frage ich nun:\ngönntest du mir wohl ein gut Gesell?\nWillst du mir das Rechte raten?\nIch lockte so oft, und erlost' es mir nie:\nDu, mein Trauter, träfst es wohl besser,\nso recht ja rietest du schon.\nNun sing'! Ich lausche dem Gesang.","translation":"Friendly little bird, I ask you now:\nWould you grant me a good companion?\nDo you want to advise me on what's right?\nI tempted so often, and never got it:\nYou, my dear friend, would probably put it better.\nYou were absolutely right.\nNow sing! I'm listening to the singing.","literalText":true,"sourceStartIndex":273,"sourceLineCount":7},{"speaker":"STIMME DES WALDVOGELS","speakerTranslation":"STIMME DES WALDVOGELS","original":"Hei! Siegfried erschlug nun den schlimmen Zwerg!\nJetzt wüsst' ich ihm noch das herrlichste Weib:\nauf hohem Felsen sie schläft,\nFeuer umbrennt ihren Saal:\ndurchschritt' er die Brunst,\nweckt' er die Braut,\nBrünnhilde wäre dann sein!","translation":"Hey! Siegfried has now slain the wicked dwarf!\nNow I know the most wonderful woman for him:\nShe sleeps on a high rock,\nFire engulfs their hall:\nHe passed through the heat,\nhe wakes the bride,\nBrünnhilde would then be his!","literalText":true,"sourceStartIndex":280,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"fährt mit jäher Heftigkeit vom Sitze auf","translation":"jumps suddenly and violently from the seat onto","literalText":true,"sourceStartIndex":287,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"O holder Sang! Süssester Hauch!\nWie brennt sein Sinn mir sehrend die Brust!\nWie zückt er heftig zündend mein Herz!\nWas jagt mir so jach durch Herz und Sinne?\nSag' es mir, süsser Freund!","translation":"O lovely song! Sweetest breath!\nHow his mind burns my breast with a burning pain!\nHow fiercely and passionately he stirs my heart!\nWhat is driving me so fast through my heart and senses?\nTell me, sweet friend!","literalText":true,"sourceStartIndex":288,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er lauscht","translation":"He listens","literalText":true,"sourceStartIndex":293,"sourceLineCount":1},{"speaker":"STIMME DES WALDVOGELS","speakerTranslation":"STIMME DES WALDVOGELS","original":"Lustig im Leid sing' ich von Liebe;\nwonnig aus Weh web' ich mein Lied:\nnur Sehnende kennen den Sinn!","translation":"Joyfully in sorrow I sing of love;\nBlissfully from sorrow I weave my song:\nOnly those who yearn know the meaning!","literalText":true,"sourceStartIndex":294,"sourceLineCount":3}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Fort jagt's mich jauchzend von hinnen,","translatedTitle":"It chases me away from behind, rejoicing,","participants":["SIEGFRIED","STIMME DES WALDVOGELS"],"sourceStartIndex":297,"sourceLineCount":23,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Fort jagt's mich jauchzend von hinnen,\nfort aus dem Wald auf den Fels!\nNoch einmal sage mir, holder Sänger:\nwerd' ich das Feuer durchbrechen?\nKann ich erwecken die Braut?","translation":"It chases me away from behind, rejoicing,\nOut of the forest and onto the rock!\nTell me once more, lovely singer:\nWill I break through the fire?\nCan I awaken the bride?","literalText":true,"sourceStartIndex":297,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried lauscht noch mal","translation":"Siegfried listens again","literalText":true,"sourceStartIndex":302,"sourceLineCount":1},{"speaker":"STIMME DES WALDVOGELS","speakerTranslation":"STIMME DES WALDVOGELS","original":"Die Braut gewinnt,\nBrünnhilde erweckt ein Feiger nie:\nnur wer das Fürchten nicht kennt!","translation":"The bride wins,\nA coward will never awaken Brünnhilde:\nOnly those who do not know fear!","literalText":true,"sourceStartIndex":303,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lacht auf vor Entzücken","translation":"laughs with delight","literalText":true,"sourceStartIndex":306,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Der dumme Knab',\nder das Fürchten nicht kennt,\nmein Vöglein, der bin ja ich!\nNoch heute gab ich vergebens mir Müh,\ndas Fürchten von Fafner zu lernen:\nnun brenn' ich vor Lust,\nes von Brünnhilde zu wissen!\nWie find' ich zum Felsen den Weg?","translation":"The stupid boy,\nwho knows no fear\nMy little bird, that's me!\nEven today I tried in vain to\nTo learn the fear of Fafner:\nNow I'm burning with lust,\nto know it from Brünnhilde!\nHow do I find my way to the rock?","literalText":true,"sourceStartIndex":307,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Der Vogel flattert auf, kreist über Siegfried und fliegt ihm zögernd voran\njauchzend","translation":"The bird flutters up, circles above Siegfried, and flies hesitantly ahead of him.\njubilant","literalText":true,"sourceStartIndex":315,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So wird mir der Weg gewiesen:\nwohin du flatterst folg' ich dem Flug!","translation":"This is how I am shown the way:\nWherever you flutter, I'll follow your flight!","literalText":true,"sourceStartIndex":317,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er läuft dem Vogel, welcher ihn neckend einige Zeitlang unstet nach verschiedenen Richtungen hinleitet, nach und folgt ihm endlich, als dieser mit einer bestimmten Wendung nach dem Hintergrunde davonfliegt. Der Vorhang fällt","translation":"He follows the bird, which teasingly leads him erratically in various directions for some time, and finally follows it when it flies off into the background with a specific turn. The curtain falls.","literalText":true,"sourceStartIndex":319,"sourceLineCount":1}]}]}];
